# Agent Performance plots and analysis generated by Github Copilot
import matplotlib.pyplot as plt
import numpy as np
import time
import os
from a3func import MsPacmanAgent as FunctionApproxAgent

class GeneralizationAnalysis:
    def __init__(self, num_seeds=5, num_episodes=100, train_episodes=1000):
        self.num_seeds = num_seeds
        self.num_episodes = num_episodes
        self.train_episodes = train_episodes
        self.seed_results = {}

    def train_agent(self, agent_class, agent_name, train_seed=0):
        print(f"\n=== Training {agent_name} with Seed {train_seed} ===")
        filename = f"generalization_{agent_name.lower().replace(' ', '_')}_weights.pkl"
        agent = agent_class(file=filename)
        np.random.seed(train_seed)
        episode_rewards = agent.run(num_episodes=self.train_episodes, learning=True)
        agent.save_weights()
        print(f"Training complete. Q-table saved to {filename}")
        return filename

    def test_agent_generalization(self, agent_class, agent_name, weights_file):
        print(f"\n=== Testing Generalization for {agent_name} ===")
        all_rewards = []
        for seed in range(self.num_seeds):
            print(f"  Testing with Seed {seed}")
            agent = agent_class(file=weights_file)
            np.random.seed(seed)
            agent.load_weights()
            episode_rewards = agent.run(num_episodes=self.num_episodes, learning=False)
            all_rewards.append(episode_rewards)
            for episode in range(self.num_episodes):
                if episode % 10 == 0:
                    recent_avg = np.mean(episode_rewards[max(0, episode-9):episode+1])
                    print(f"    Seed {seed}, Episode {episode}: Avg Reward = {recent_avg:.1f}")
        self.seed_results[agent_name] = {
            'all_rewards': all_rewards,
            'learning_curves': [self.calculate_learning_curve(rewards) for rewards in all_rewards]
        }
        return all_rewards

    def calculate_learning_curve(self, rewards, window=50):
        learning_curve = []
        for i in range(len(rewards)):
            start_idx = max(0, i - window + 1)
            learning_curve.append(np.mean(rewards[start_idx:i+1]))
        return learning_curve

    def create_generalization_plot(self, agent_name):
        if agent_name not in self.seed_results:
            print(f"No data for {agent_name}")
            return
        data = self.seed_results[agent_name]
        plt.figure(figsize=(10, 6))
        episodes = np.arange(self.num_episodes)
        colors = plt.cm.Set3(np.linspace(0, 1, self.num_seeds))
        plt.title(f'{agent_name}: Generalization Across Seeds', fontsize=14)
        for i, learning_curve in enumerate(data['learning_curves']):
            plt.plot(episodes, learning_curve, label=f'Seed {i}', color=colors[i], alpha=0.7, linewidth=1)
        mean_learning_curve = np.mean(data['learning_curves'], axis=0)
        plt.plot(episodes, mean_learning_curve, label='Mean', color='black', linewidth=3)
        plt.xlabel('Episodes')
        plt.ylabel('Average Reward (50-episode window)')
        plt.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
        plt.grid(True, alpha=0.3)
        plt.tight_layout()
        plt.savefig(f'{agent_name.lower().replace(" ", "_")}_generalization_across_seeds.png', dpi=300, bbox_inches='tight')
        plt.show()

def main():
    NUM_SEEDS = 5
    NUM_EPISODES = 100
    TRAIN_EPISODES = 1000
    agent_name = "Function Approximation Agent"
    analysis = GeneralizationAnalysis(num_seeds=NUM_SEEDS, num_episodes=NUM_EPISODES, train_episodes=TRAIN_EPISODES)
    weights_file = analysis.train_agent(FunctionApproxAgent, agent_name, train_seed=0)
    analysis.test_agent_generalization(FunctionApproxAgent, agent_name, weights_file)
    analysis.create_generalization_plot(agent_name)
    print(f"\nAnalysis complete! Generated:")
    print(f"  - {agent_name.lower().replace(' ', '_')}_generalization_across_seeds.png")

if __name__ == "__main__":
    main()